// Reads the rules the customer can edit (mf.settings and mf.reason_codes) into global context
// as  global.get('cfg') . Runs every 10 seconds, so a change in Studio is live within 10 s.
const db = global.get('db');
const lib = global.get('lib');
if (!lib) return null;                                   // library not started yet

const s = await db.query('SELECT key, value FROM mf.settings');
const r = await db.query('SELECT code, description, asset_type, severity, assigned_to FROM mf.reason_codes WHERE active');

const cfg = {};
s.rows.forEach((row) => { cfg[row.key] = row.value; });
cfg.reasons = {};
r.rows.forEach((row) => { cfg.reasons[row.code] = row; });
global.set('cfg', cfg);

node.status({ text: `${s.rows.length} settings, ${r.rows.length} reason codes @ ${new Date().toLocaleTimeString()}` });
return null;

// Every MQTT message from a machine lands here.
// topic: mf/v1/site/{site}/asset/{asset}/{telemetry|status|event}
const p = msg.topic.split('/');
if (p.length !== 7 || p[0] !== 'mf' || p[1] !== 'v1' || p[2] !== 'site' || p[4] !== 'asset') {
    node.warn(`ignored topic ${msg.topic}`);
    return null;
}
const [site, asset, type] = [p[3], p[5], p[6]];
if (type === 'command') return null;                  // our own outbound commands
if (!['telemetry', 'status', 'event'].includes(type)) {
    node.warn(`unknown message type '${type}' on ${msg.topic}`);
    return null;
}
let body;
try { body = JSON.parse(msg.payload); }
catch (e) { node.warn(`invalid JSON on ${msg.topic}`); return null; }
if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    node.warn(`payload must be a JSON object on ${msg.topic}`); return null;
}
msg.mf = { site, asset, type };
msg.body = body;
node.status({ text: `${asset} ${type} @ ${new Date().toLocaleTimeString()}` });
return [type === 'telemetry' ? msg : null, type === 'status' ? msg : null, type === 'event' ? msg : null];

// Store signal readings: one row per signal in mf.telemetry, and the latest value on mf.asset_signals.
const db = global.get('db');
const lib = global.get('lib');
const { site, asset } = msg.mf;
const body = msg.body;

const a = await lib.findAsset(site, asset);
if (!a) return [null, { topic: msg.topic, payload: { error: 'unknown_asset', site, asset } }];
if (!body.signals || typeof body.signals !== 'object' || Array.isArray(body.signals)) {
    return [null, { topic: msg.topic, payload: { error: 'signals_object_required' } }];
}
const ts = lib.parseTs(body.timestamp) || new Date();

await db.tx(async (c) => {
    await c.query('UPDATE mf.assets SET last_seen_at = GREATEST(COALESCE(last_seen_at, $2::timestamptz), $2::timestamptz) WHERE id = $1', [a.id, ts]);
    for (const [name, value] of Object.entries(body.signals)) {
        if (value === null || value === undefined) continue;
        const isNum = typeof value === 'number' && Number.isFinite(value);
        const num = isNum ? value : null;
        const txt = isNum ? null : (typeof value === 'object' ? JSON.stringify(value) : String(value));
        const unit = body.units && body.units[name] != null ? String(body.units[name]) : null;
        const sig = await c.query(
            `INSERT INTO mf.asset_signals (asset_id, signal_name, data_type, unit)
             VALUES ($1, $2, $3, $4)
             ON CONFLICT (asset_id, signal_name) DO UPDATE SET unit = COALESCE(EXCLUDED.unit, mf.asset_signals.unit)
             RETURNING id`, [a.id, name, isNum ? 'numeric' : 'text', unit]);
        const sid = sig.rows[0].id;
        await c.query(
            `INSERT INTO mf.telemetry (asset_id, signal_id, value_numeric, value_text, recorded_at)
             VALUES ($1, $2, $3, $4, $5)`, [a.id, sid, num, txt, ts]);
        await c.query(
            `UPDATE mf.asset_signals SET last_value_numeric = $2, last_value_text = $3, last_recorded_at = $4
              WHERE id = $1`, [sid, num, txt, ts]);
    }
});
return null;

// A machine reports its state. Keep mf.assets current and open or close downtime.
// Outputs: 1 = downtime opened (goes to "04 Alerts & Maintenance"), 2 = downtime closed, 3 = rejected.
const db = global.get('db');
const lib = global.get('lib');
const { site, asset } = msg.mf;
const body = msg.body;

const status = String(body.status || '').toLowerCase();
if (!lib.STATUSES.includes(status)) {
    return [null, null, { topic: msg.topic, payload: { error: 'invalid_status', status: body.status } }];
}
const a = await lib.findAsset(site, asset);
if (!a) return [null, null, { topic: msg.topic, payload: { error: 'unknown_asset', site, asset } }];

const ts = lib.parseTs(body.timestamp) || new Date();
const cfg = lib.cfg();
const isDown = cfg.downtime_statuses.includes(status);

// reason text: what the machine said, else the catalogue entry for its reason code
const code = body.reason_code ? String(body.reason_code) : null;
const catalogue = lib.reason(code);
const reasonText = body.reason_description ? String(body.reason_description)
                 : (catalogue ? catalogue.description : null);

let opened = null, closed = null;
await db.tx(async (c) => {
    const cur = (await c.query('SELECT status FROM mf.assets WHERE id = $1 FOR UPDATE', [a.id])).rows[0];
    await c.query('UPDATE mf.assets SET last_seen_at = GREATEST(COALESCE(last_seen_at, $2::timestamptz), $2::timestamptz) WHERE id = $1', [a.id, ts]);
    if (cur.status !== status) {
        await c.query('UPDATE mf.assets SET status = $2, status_changed_at = $3 WHERE id = $1', [a.id, status, ts]);
    }
    const open = (await c.query('SELECT * FROM mf.downtime_events WHERE asset_id = $1 AND ended_at IS NULL', [a.id])).rows[0];
    let stillOpen = open;
    // close the open downtime if the machine recovered or moved to a different downtime state
    if (open && (!isDown || open.status !== status)) {
        closed = (await c.query(
            `UPDATE mf.downtime_events
                SET ended_at = $2::timestamptz,
                    duration_seconds = GREATEST(0, EXTRACT(EPOCH FROM ($2::timestamptz - started_at)))::int
              WHERE id = $1 RETURNING *`, [open.id, ts])).rows[0];
        stillOpen = null;
    }
    if (isDown && !stillOpen) {
        opened = (await c.query(
            `INSERT INTO mf.downtime_events (asset_id, status, reason_code, reason_description, started_at)
             VALUES ($1, $2, $3, $4, $5) RETURNING *`, [a.id, status, code, reasonText, ts])).rows[0];
    }
});

const ctx = { asset: a };
return [
    opened ? { topic: msg.topic, payload: opened, ctx } : null,
    closed ? { topic: msg.topic, payload: closed, ctx } : null,
    null,
];

// A machine reports something that happened: online, order_started, cycle_complete, fault_cleared ...
// This is where parts are counted against the active order and where an order is completed.
// Outputs: 1 = command to the machine, 2 = production receipt for the ERP, 3 = rejected.
const db = global.get('db');
const lib = global.get('lib');
const { site, asset } = msg.mf;
const body = msg.body;

const ev = String(body.event_type || '').toLowerCase();
if (!ev) return [null, null, { topic: msg.topic, payload: { error: 'event_type_required' } }];
const a = await lib.findAsset(site, asset);
if (!a) return [null, null, { topic: msg.topic, payload: { error: 'unknown_asset', site, asset } }];

const ts = lib.parseTs(body.timestamp) || new Date();
// quantity must be a whole number from 1 to 1000; anything else counts as 1
const q = Number(body.quantity);
const qty = Number.isInteger(q) && q >= 1 && q <= 1000 ? q : 1;

let completed = null;
await db.tx(async (c) => {
    await c.query('UPDATE mf.assets SET last_seen_at = GREATEST(COALESCE(last_seen_at, $2::timestamptz), $2::timestamptz) WHERE id = $1', [a.id, ts]);

    // a device that (re)started has lost its work: hand running orders back to be re-sent
    if (ev === 'online') {
        await c.query(`UPDATE mf.production_orders SET status = 'released' WHERE asset_id = $1 AND status = 'running'`, [a.id]);
    }

    let order;
    if (ev === 'order_started') {
        order = (await c.query(
            `UPDATE mf.production_orders SET status = 'running', started_at = COALESCE(started_at, $3::timestamptz)
              WHERE asset_id = $1 AND order_number = $2 AND status IN ('released','running') RETURNING *`,
            [a.id, body.order_number || null, ts])).rows[0];
    } else {
        order = (await c.query(
            `SELECT * FROM mf.production_orders WHERE asset_id = $1 AND status = 'running'
              ORDER BY started_at LIMIT 1`, [a.id])).rows[0];
    }

    await c.query(
        `INSERT INTO mf.production_events (asset_id, production_order_id, event_type, quantity, event_time, metadata)
         VALUES ($1, $2, $3, $4, $5, $6::jsonb)`,
        [a.id, order ? order.id : null, ev, qty, ts, JSON.stringify(body)]);

    if (ev === 'cycle_complete') {
        let result = String(body.quality_result || 'good').toLowerCase();
        if (!['good', 'scrap', 'rework'].includes(result)) result = 'good';
        await c.query(
            `INSERT INTO mf.quality_events (asset_id, production_order_id, part_number, result, defect_code, event_time)
             VALUES ($1, $2, $3, $4, $5, $6)`,
            [a.id, order ? order.id : null,
             body.part_number || (order && order.part_number) || a.default_part_number,
             result, body.defect_code || null, ts]);

        if (order) {
            const upd = (await c.query(
                `UPDATE mf.production_orders
                    SET completed_quantity = completed_quantity + $2, scrap_quantity = scrap_quantity + $3
                  WHERE id = $1 RETURNING *`,
                [order.id, result === 'good' ? qty : 0, result === 'good' ? 0 : qty])).rows[0];
            if (upd.completed_quantity >= upd.target_quantity) {
                // "AND status = 'running'" makes sure an order is completed, and its receipt sent, only once
                const done = (await c.query(
                    `UPDATE mf.production_orders SET status = 'complete', completed_at = $2
                      WHERE id = $1 AND status = 'running' RETURNING *`, [order.id, ts])).rows[0];
                if (done) {
                    completed = {
                        order_number: done.order_number, part_number: done.part_number,
                        good_quantity: done.completed_quantity, scrap_quantity: done.scrap_quantity,
                        completed_at: done.completed_at, site, asset,
                    };
                }
            }
        }
    }
});

if (!completed) return null;

node.status({ fill: 'green', shape: 'dot', text: `${completed.order_number} complete` });
// 1) tell the machine the order is finished
const cmd = {
    topic: `mf/v1/site/${site}/asset/${asset}/command`,
    payload: { command: 'complete_order', order_number: completed.order_number },
};
// 2) send the production receipt back to the (demo) ERP
const receipt = {
    method: 'POST',
    url: 'http://127.0.0.1:1880/demo-erp/receipts',
    headers: { 'content-type': 'application/json', authorization: 'Bearer ' + env.get('MF_API_TOKEN') },
    payload: completed,
};
return [cmd, receipt, null];

// GET /api/v1/health: public (uptime monitors), no token needed
const db = global.get('db');
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
try {
    const r = await db.query('SELECT now() AS db_time');
    msg.statusCode = 200;
    msg.payload = { status: 'ok', service: 'manufaction', version: env.get('MF_VERSION') || '2.0.0', db_time: r.rows[0].db_time };
} catch (e) {
    msg.statusCode = 503;
    msg.payload = { error: 'database_unavailable' };
}
return [msg, null];

// GET /api/v1/assets: every machine with live status, latest signals, active order, open downtime
const lib = global.get('lib');
const db = global.get('db');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return [msg, null];
}
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

msg.payload = await lib.assetViews(null, null);
msg.statusCode = 200;
return [msg, null];

// GET /api/v1/assets/:asset_code
const lib = global.get('lib');
const db = global.get('db');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return [msg, null];
}
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

const list = await lib.assetViews(null, String(msg.req.params.asset_code));
if (!list.length) { msg.statusCode = 404; msg.payload = { error: 'not_found' }; return [msg, null]; }
msg.statusCode = 200; msg.payload = list[0];
return [msg, null];

// GET /api/v1/production: the 50 most recent orders
const lib = global.get('lib');
const db = global.get('db');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return [msg, null];
}
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

const rows = (await db.query(`${lib.ORDER_SQL} ORDER BY o.released_at DESC LIMIT 50`)).rows;
msg.statusCode = 200; msg.payload = rows.map(lib.orderView);
return [msg, null];

// GET /api/v1/production/:order_number
const lib = global.get('lib');
const db = global.get('db');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return [msg, null];
}
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

const rows = (await db.query(`${lib.ORDER_SQL} WHERE o.order_number = $1`, [String(msg.req.params.order_number)])).rows;
if (!rows.length) { msg.statusCode = 404; msg.payload = { error: 'not_found' }; return [msg, null]; }
msg.statusCode = 200; msg.payload = lib.orderView(rows[0]);
return [msg, null];

// GET /api/v1/downtime: the 50 most recent downtime events
const lib = global.get('lib');
const db = global.get('db');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return [msg, null];
}
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

const rows = (await db.query(
    `SELECT s.site_code AS site, a.asset_code AS asset, d.status, d.reason_code, d.reason_description,
            d.started_at, d.ended_at, d.duration_seconds
       FROM mf.downtime_events d
       JOIN mf.assets a ON a.id = d.asset_id
       JOIN mf.sites s ON s.id = a.site_id
      ORDER BY d.started_at DESC LIMIT 50`)).rows;
msg.statusCode = 200; msg.payload = rows;
return [msg, null];

// POST /api/v1/production-orders: release an order to a machine
const lib = global.get('lib');
const db = global.get('db');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return [msg, null];
}
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

const b = msg.payload || {};
const asset = b.asset || b.asset_id;
const qty = Number(b.target_quantity);
if (!asset || !b.order_number) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'asset and order_number are required' }; return [msg, null]; }
if (!Number.isInteger(qty) || qty <= 0 || qty > 1000000) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'target_quantity must be a positive integer' }; return [msg, null]; }
const r = await lib.createOrder({
    site: String(b.site || 'demo'), asset: String(asset), order_number: String(b.order_number),
    part_number: b.part_number ? String(b.part_number) : null, target_quantity: qty,
    source_system: String(b.source_system || 'API'),
});
msg.statusCode = r.status_code;
if (!r.order) { msg.payload = { error: r.error, detail: r.detail }; return [msg, null]; }
msg.payload = r.order;
return [msg, lib.startCommand(r.order)];        // tell the machine to start right away

// POST /api/v1/telemetry: accepted and published to MQTT
const lib = global.get('lib');
const db = global.get('db');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return [msg, null];
}
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

const b = (msg.payload && typeof msg.payload === 'object') ? Object.assign({}, msg.payload) : null;
