const asset = b.asset || b.asset_id;
const site = String(b.site || 'demo');
if (!asset || !/^[A-Za-z0-9_.-]+$/.test(asset) || !/^[A-Za-z0-9_.-]+$/.test(site))
    { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'valid asset (and optional site) required' }; return [msg, null]; }
const TYPE = 'telemetry';
if (TYPE === 'telemetry' && (typeof b.signals !== 'object' || b.signals === null)) {
    // accept flat bodies: { asset_id, temperature: 186.4, pressure: 1840 }
    const signals = {};
    for (const [k, v] of Object.entries(b)) {
        if (!['site', 'asset', 'asset_id', 'timestamp', 'units'].includes(k)) signals[k] = v;
    }
    b.signals = signals;
}
if (TYPE === 'event' && !b.event_type) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'event_type required' }; return [msg, null]; }
if (TYPE === 'status' && !b.status) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'status required' }; return [msg, null]; }
b.timestamp = b.timestamp || new Date().toISOString();
// Publish to MQTT: the REST path and the device path then go through exactly the same ingestion flow.
const pub = { topic: `mf/v1/site/${site}/asset/${asset}/${TYPE}`, payload: JSON.stringify(b) };
msg.statusCode = 202;
msg.payload = { accepted: true, topic: pub.topic };
return [msg, pub];

