// Re-send start_order to machines that have a released order but have not acknowledged it yet.
// (The machine confirms with an order_started event; until then the order stays "released".)
const db = global.get('db');
const lib = global.get('lib');
const cfg = lib.cfg();

// the tick runs every 5 s; only act as often as the "dispatch_retry_seconds" setting says
const last = context.get('last') || 0;
if (Date.now() - last < cfg.dispatch_retry_seconds * 1000 - 500) return null;
context.set('last', Date.now());

const rows = (await db.query(
    `SELECT s.site_code AS site, a.asset_code AS asset, o.order_number, o.part_number, o.target_quantity,
            a.status, a.last_seen_at
       FROM mf.production_orders o
       JOIN mf.assets a ON a.id = o.asset_id
       JOIN mf.sites s ON s.id = o.site_id
      WHERE o.status = 'released'`)).rows
    .filter((r) => lib.effectiveStatus(r.status, r.last_seen_at) !== 'offline');

node.status({ text: `${rows.length} dispatched @ ${new Date().toLocaleTimeString()}` });
return [rows.map((r) => lib.startCommand(r))];

// A machine went down. Decide what the plant needs to know and who must act:
//   * a dashboard alert              (statuses listed in the "alert_statuses" setting)
//   * a maintenance work request     (statuses listed in "work_request_statuses")
// Who gets the work request, and how serious it is, comes from the reason code catalogue.
const db = global.get('db');
const lib = global.get('lib');
const cfg = lib.cfg();
const d = msg.payload;                    // the new mf.downtime_events row
const a = msg.ctx.asset;                  // the machine

const reason = lib.reason(d.reason_code);
const what = d.reason_description || (reason && reason.description) || d.reason_code || 'No reason reported';
const severity = reason && reason.severity ? reason.severity : 'critical';
const assignee = (reason && reason.assigned_to) || cfg.default_assignee;
let workRequest = null;

await db.tx(async (c) => {
    if (!d.reason_description && what !== 'No reason reported') {
        await c.query('UPDATE mf.downtime_events SET reason_description = $2 WHERE id = $1', [d.id, what]);
    }
    if (cfg.alert_statuses.includes(d.status)) {
        await c.query(
            `INSERT INTO mf.notifications (kind, severity, asset_id, downtime_event_id, title, message, created_at)
             VALUES ('downtime_alert', $1, $2, $3, $4, $5, $6)`,
            [severity, a.id, d.id, `${a.asset_code} ${d.status}`, what, d.started_at]);
    }
    if (cfg.work_request_statuses.includes(d.status)) {
        // WR-YYMMDD-NNN : date in the plant's own time zone, running number from a database sequence
        const n = (await c.query(
            `SELECT 'WR-' || to_char($1::timestamptz AT TIME ZONE $2, 'YYMMDD') || '-'
                    || lpad(nextval('mf.work_request_seq')::text, 3, '0') AS number`,
            [d.started_at, a.timezone])).rows[0].number;
        workRequest = n;
        await c.query(
            `INSERT INTO mf.maintenance_requests
                    (request_number, asset_id, downtime_event_id, reason_code, description, assigned_to, opened_at)
             VALUES ($1, $2, $3, $4, $5, $6, $7)`,
            [n, a.id, d.id, d.reason_code, what, assignee, d.started_at]);
        await c.query(
            `INSERT INTO mf.notifications (kind, severity, asset_id, downtime_event_id, title, message, created_at)
             VALUES ('maintenance_dispatched', 'info', $1, $2, 'Maintenance notified', $3,
                     $4::timestamptz + interval '1 second')`,
            [a.id, d.id, `${n} sent to ${assignee} for ${a.asset_code}`, d.started_at]);
    }
});

node.status({ fill: 'red', shape: 'dot', text: `${a.asset_code} ${d.status}${workRequest ? ' ' + workRequest : ''}` });
return null;

// A machine came back. Close its work request and tell the plant it is producing again.
const db = global.get('db');
const lib = global.get('lib');
const cfg = lib.cfg();
const d = msg.payload;                    // the downtime row, now with ended_at and duration_seconds
const a = msg.ctx.asset;

await db.tx(async (c) => {
    await c.query(
        `UPDATE mf.maintenance_requests SET status = 'closed', closed_at = $2
          WHERE downtime_event_id = $1 AND status = 'open'`, [d.id, d.ended_at]);
    if (cfg.alert_statuses.includes(d.status)) {
        await c.query(
            `INSERT INTO mf.notifications (kind, severity, asset_id, downtime_event_id, title, message, created_at)
             VALUES ('recovered', 'success', $1, $2, $3, $4, $5)`,
            [a.id, d.id, `${a.asset_code} back in production`,
             `Down for ${lib.fmtDuration(d.duration_seconds)}`, d.ended_at]);
    }
});
node.status({ fill: 'green', shape: 'dot', text: `${a.asset_code} recovered` });
return null;

// Every 5 s: find alerts that have not been delivered yet.
// Delivery is off until MF_NOTIFY_WEBHOOK_URL is set in .env.
// A failed send is retried up to 5 times, 15 s apart; anything older than 15 minutes is dropped,
// so switching delivery on never replays old alerts.
const db = global.get('db');
if (!env.get('MF_NOTIFY_WEBHOOK_URL')) {
    node.status({ fill: 'grey', shape: 'ring', text: 'disabled (no MF_NOTIFY_WEBHOOK_URL)' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: 'enabled' });

const rows = (await db.query(
    `SELECT n.id, n.kind, n.severity, n.title, n.message, n.created_at,
            s.site_code, a.asset_code,
            r.request_number AS work_request, r.reason_code, r.description AS wr_description, r.assigned_to
       FROM mf.notifications n
       LEFT JOIN mf.assets a ON a.id = n.asset_id
       LEFT JOIN mf.sites s ON s.id = a.site_id
       LEFT JOIN mf.maintenance_requests r ON r.downtime_event_id = n.downtime_event_id
      WHERE NOT n.seeded
        AND n.delivered_at IS NULL
        AND n.delivery_attempts < 5
        AND n.created_at > NOW() - INTERVAL '15 minutes'
        AND (n.last_attempt_at IS NULL OR n.last_attempt_at < NOW() - INTERVAL '15 seconds')
        AND NOT (n.kind = 'downtime_alert' AND r.id IS NOT NULL)   -- the work-request message covers it
      ORDER BY n.created_at, n.id
      LIMIT 10`)).rows;
if (!rows.length) return null;

// Wording of each message. Change the text here to change what people receive.
const text = (r) => {
    switch (r.kind) {
        case 'maintenance_dispatched':
            return `FAULT: ${r.asset_code} - ${r.wr_description || 'no reason reported'}. Work request ${r.work_request} sent to ${r.assigned_to}.`;
        case 'downtime_alert':
            return `STOPPED: ${r.asset_code} has stopped (${r.message || 'no reason reported'}).`;
        case 'recovered':
            return `BACK IN PRODUCTION: ${r.asset_code} - ${r.message || ''}.`;
        default:
            return 'TEST: Manufaction notifications are working.';
    }
};
return [rows.map((r) => Object.assign({}, r, { text: text(r) })).map((r) => ({ payload: r }))];

// Shape one alert for the destination chosen by MF_NOTIFY_FORMAT:
//   json (default, full event for Zapier / Make / your own endpoint) | slack | discord | text (ntfy.sh)
const url = env.get('MF_NOTIFY_WEBHOOK_URL');
const fmt = (env.get('MF_NOTIFY_FORMAT') || 'json').toLowerCase();
const token = env.get('MF_NOTIFY_BEARER_TOKEN');
const oneLine = (s) => String(s == null ? '' : s).replace(/[\r\n]+/g, ' ');
const r = msg.payload;

const m = { notification_id: r.id, method: 'POST', url, headers: {} };
if (token) m.headers.authorization = 'Bearer ' + token;
if (fmt === 'slack') {                    // Slack / Mattermost incoming webhook
    m.headers['content-type'] = 'application/json';
    m.payload = { text: r.text };
} else if (fmt === 'discord') {
    m.headers['content-type'] = 'application/json';
    m.payload = { content: r.text };
} else if (fmt === 'text') {              // ntfy.sh and similar: plain-text body
    m.headers['content-type'] = 'text/plain; charset=utf-8';
    m.headers.title = oneLine(r.title);
    m.payload = r.text;
} else {
    m.headers['content-type'] = 'application/json';
    m.payload = {
        source: 'manufaction', event: r.kind, severity: r.severity, site: r.site_code,
        asset: r.asset_code, title: r.title, message: r.text,
        work_request: r.work_request, reason_code: r.reason_code, occurred_at: r.created_at,
    };
}
return m;

// The webhook answered. Record the outcome so a failed alert is retried and a delivered one is not.
const db = global.get('db');
const ok = msg.statusCode >= 200 && msg.statusCode < 300;
if (!ok) node.warn('webhook returned HTTP ' + msg.statusCode + ' for notification ' + msg.notification_id);
await db.query(
    `UPDATE mf.notifications
        SET delivered_at = CASE WHEN $2 THEN NOW() ELSE delivered_at END,
            delivery_attempts = delivery_attempts + 1,
            last_attempt_at = NOW(),
            last_error = CASE WHEN $2 THEN NULL ELSE left($3, 200) END
      WHERE id = $1 AND delivered_at IS NULL`,
    [msg.notification_id, ok, ok ? null : 'HTTP ' + msg.statusCode]);
return null;

// The webhook could not be reached (DNS, refused, timeout). Keep the message short and never log the URL:
// Slack and Teams webhook URLs contain a secret token.
const db = global.get('db');
if (msg.notification_id == null) return null;
const why = String((msg.error && msg.error.message) || 'request failed').replace(/https?:\/\/\S+/g, '[url]').slice(0, 150);
node.warn('webhook send failed for notification ' + msg.notification_id + ': ' + why);
await db.query(
    `UPDATE mf.notifications
        SET delivery_attempts = delivery_attempts + 1, last_attempt_at = NOW(), last_error = left($2, 200)
      WHERE id = $1 AND delivered_at IS NULL`, [msg.notification_id, why]);
return null;

// DEMO ERP: stands in for a customer ERP. Every 20 s, any machine that is online and has no open
// order gets a new work order, released through the public REST API (the same call a real ERP would make).
// Order size depends on the machine type. Switch off with DEMO_ERP_ENABLED=false in .env.
if (env.get('DEMO_ERP_ENABLED') === 'false') return null;
const db = global.get('db');
const lib = global.get('lib');

const SIZE = { press: [30, 60], cnc: [8, 16], assembly: [12, 24] };
const rows = (await db.query(
    `SELECT s.site_code, a.asset_code, a.asset_type, a.default_part_number AS part_number, a.status, a.last_seen_at
       FROM mf.assets a JOIN mf.sites s ON s.id = a.site_id
      WHERE NOT EXISTS (SELECT 1 FROM mf.production_orders o
                         WHERE o.asset_id = a.id AND o.status IN ('released','running'))`)).rows
    .filter((r) => lib.effectiveStatus(r.status, r.last_seen_at) !== 'offline' && r.part_number);

const stamp = new Date().toISOString().slice(2, 10).replace(/-/g, '');
return [rows.map((a) => {
    const [lo, hi] = SIZE[a.asset_type] || [10, 20];
    return {
        method: 'POST', url: 'http://127.0.0.1:1880/api/v1/production-orders',
        headers: { 'content-type': 'application/json', authorization: 'Bearer ' + env.get('MF_API_TOKEN') },
        payload: {
            site: a.site_code, asset: a.asset_code, part_number: a.part_number,
            order_number: `MO-${stamp}-${Math.floor(Math.random() * 9000 + 1000)}`,
            target_quantity: Math.floor(Math.random() * (hi - lo + 1)) + lo,
            source_system: 'DEMO-ERP',
        },
    };
})];

// DEMO ERP: receives the production receipt that Manufaction sends when an order completes.
const db = global.get('db');
const lib = global.get('lib');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return msg;
}
const p = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!p.order_number) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'order_number required' }; return msg; }
const num = (v) => (Number.isInteger(Number(v)) ? Number(v) : null);
const r = await db.query(
    `INSERT INTO demo_erp.production_receipts
            (order_number, part_number, good_quantity, scrap_quantity, completed_at, payload)
     VALUES ($1, $2, $3, $4, $5, $6::jsonb) RETURNING id`,
    [String(p.order_number), p.part_number || null, num(p.good_quantity), num(p.scrap_quantity),
     lib.parseTs(p.completed_at), JSON.stringify(p)]);
msg.statusCode = 201;
msg.payload = { ok: true, receipt_id: r.rows[0].id };
node.status({ fill: 'blue', shape: 'dot', text: `receipt ${r.rows[0].id}` });
return msg;

if (!msg.res) { node.warn(msg.error && msg.error.message); return null; }
msg.statusCode = 500; msg.payload = { error: 'internal_error' };
return msg;

// Nightly housekeeping: delete raw telemetry older than the "telemetry_keep_days" setting.
const db = global.get('db');
const lib = global.get('lib');
const days = Number(lib.cfg().telemetry_keep_days) || 7;
const r = await db.query(`DELETE FROM mf.telemetry WHERE recorded_at < NOW() - make_interval(days => $1::int)`, [days]);
node.status({ text: `purged ${r.rowCount} rows (older than ${days} days) @ ${new Date().toLocaleTimeString()}` });
return null;
